'use strict';
const $ = id => document.getElementById(id);
const mainScroll = () => $('main-scroll');
function scrollMain(top = 0) { const root = mainScroll(); if (root) root.scrollTop = top; }
const labels = {recommend:'推荐',discover:'找剧',rankings:'排行榜',new:'新剧',search:'搜索剧集',actors:'剧星榜',favorites:'收藏',history:'观看记录',likes:'点赞',tasks:'下载管理',settings:'连接设置',mine:'我的',series:'剧集详情',actor:'演员主页',player:'在线播放'};
const viewSubtitles = {recommend:'今晚看点',discover:'按题材找剧',rankings:'真实热度',new:'最新片单',search:'按剧名或演员搜索',actors:'演员与作品',favorites:'保存在本机',history:'上次看到这里',likes:'你点过赞的故事',tasks:'下载与转换任务',settings:'播放与连接',mine:'本机观看空间',series:'了解这部剧',actor:'演员作品',player:'沉浸观看'};
function hashForView(view) {
  if (view === 'rankings') return '#/rank';
  if (view === 'new') return '#/new';
  if (view === 'mine') return '#/mine';
  if (view === 'recommend') return '#/recommend';
  if (view === 'likes') return '#/likes';
  return '#/' + view;
}
function read(key) { try { const value=JSON.parse(localStorage.getItem('hg-web-'+key)||'[]'); return Array.isArray(value)?value:[]; } catch {return [];} }
const state={mergeSelected:new Set(),genre:'',actorPage:1,gender:'all',recent:read('searches'),token:'',owner:false,generation:0,view:'recommend',category:'real-drama',catalogPage:1,searchPage:1,query:'',tasks:[],favorites:read('favorites'),history:read('history'),likes:read('likes'),series:null,selected:new Set(),playing:null,pendingPlay:null,request:0,detailRequest:0};
let eventController, playerRequest=0, playController, streamUrl;let episodePage=0; const requests=new Set();
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function action(text,fn,cls){const b=node('button',text,cls);b.type='button';b.addEventListener('click',async()=>{try{await fn();}catch(e){notice(e);}});return b;}
function notice(value){$('notice').textContent=value?.message||String(value||'');$('notice').hidden=!value;}
function save(key){try{localStorage.setItem('hg-web-'+key,JSON.stringify(state[key]));}catch{notice('浏览器存储不可写，本次记录无法保存。');}}
async function requestApi(path,payload,outerSignal){if(!state.token)throw Error('请先在连接设置中输入访问令牌。');const generation=state.generation;const c=new AbortController();requests.add(c);const abort=()=>c.abort();outerSignal?.addEventListener('abort',abort,{once:true});if(outerSignal?.aborted)c.abort();const t=setTimeout(()=>c.abort(),35000);try{const res=await fetch('/api'+path,{method:payload===undefined?'GET':'POST',headers:{...(state.token!=='public'?{Authorization:'Bearer '+state.token}:{}),...(payload!==undefined?{'Content-Type':'application/json'}:{})},body:payload===undefined?undefined:JSON.stringify(payload),signal:c.signal,credentials:'same-origin'});const data=await res.json();if(generation!==state.generation)throw Error('连接已断开');if(!res.ok||data.success===false)throw Error(data.error||'请求失败');return data;}catch(e){if(e.name==='AbortError')throw Error('请求已取消或超时，请手动重试。');throw e;}finally{clearTimeout(t);outerSignal?.removeEventListener('abort',abort);requests.delete(c);}}
const dataCache=new Map(), inFlight=new Map(), timings=[];
async function api(path,payload,signal){
 const cacheable=payload===undefined&&/^\/(?:catalog|search|series|actors|seasons)(?:[/?]|$)/.test(path);
 const hit=dataCache.get(path);if(cacheable&&hit?.expires>Date.now())return hit.data;
 if(cacheable&&!signal&&inFlight.has(path))return inFlight.get(path);
 const generation=state.generation,t=performance.now();
 const pending=requestApi(path,payload,signal).then(data=>{const ms=Math.round(performance.now()-t);timings.unshift({route:path.split('?')[0].replace(/\d{6,}/g,':id'),ms,at:new Date().toISOString()});timings.length=Math.min(30,timings.length);$('last-timing').textContent=`最近请求 ${ms} 毫秒 · ${path.split('?')[0].replace(/\d{6,}/g,':id')}`;if(cacheable&&generation===state.generation){dataCache.set(path,{data,expires:Date.now()+120000});while(dataCache.size>100)dataCache.delete(dataCache.keys().next().value);}return data;}).finally(()=>{if(inFlight.get(path)===pending)inFlight.delete(path);});
 if(cacheable&&!signal)inFlight.set(path,pending);return pending;
}
function empty(target,title,description,connect=false){const el=node('div',undefined,'empty');el.append(node('strong',title),node('p',description));if(connect)el.append(action('连接我的短剧馆',()=>showView('settings'),'primary'));$(target).replaceChildren(el);}
function requireConnection(target){if(state.token)return true;empty(target,'好故事，等你来发现','连接红果服务后，这里将展示真实剧集。',true);return false;}
const scrollPositions=new Map();
function showView(view,fromHistory=false){
 if(!labels[view])return;if(view==='tasks'&&!state.owner){showView('settings');notice('下载与任务管理仅限本人，请使用本人管理授权入口登录。');return;}if(!fromHistory&&view!=='settings'&&!state.token)state.authTarget=null;
 const old=state.view;if(old!==view){scrollPositions.set(old,mainScroll()?.scrollTop||0);if(old==='player')stopPlayback();if(old==='series')state.detailRequest++;if(old==='actor')actorDetailRequest++;}
 state.view=view;for(const name of Object.keys(labels)){const panel=$('view-'+name);if(panel)panel.hidden=name!==view;}
 const active=['series','player'].includes(view)?(state.returnView||'discover'):view==='actor'?'actors':view;
 document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===active));$('crumb').textContent=labels[view];$('topbar-sub').textContent=viewSubtitles[view]||'';document.title=`${labels[view]} · 红果剧场`;notice('');
 if(!fromHistory&&!['series','actor','player'].includes(view))window.history.pushState({view},'',hashForView(view)+(view==='search'&&state.query?'?q='+encodeURIComponent(state.query)+'&page='+state.searchPage:''));
 if(view==='favorites')renderSaved('favorites');if(view==='history')renderSaved('history');if(view==='likes')renderSaved('likes');if(view==='tasks')renderTasks();if(view==='actors')loadActors();if(view==='search')renderRecent();if(view==='recommend')loadHome();if(view==='discover')loadCatalog();if(view==='rankings')loadRanking();if(view==='new')loadNew();if(view==='mine')renderMine();
 scrollMain(fromHistory?(scrollPositions.get(view)||0):0);closeSidebarNav();
}
for(const b of document.querySelectorAll('[data-view]'))b.addEventListener('click',()=>showView(b.dataset.view));$('connect-top').onclick=()=>showView('settings');
function image(url,alt=''){try{const u=new URL(url);if(u.protocol!=='https:'||u.username||u.password)return null;const img=node('img');img.src=u.href;img.alt=alt;img.loading='lazy';img.referrerPolicy='no-referrer';img.onerror=()=>img.remove();return img;}catch{return null;}}
function renderCards(target,items){$(target).replaceChildren();for(const item of items){const card=action('',()=>openSeries(item),'poster');const cover=node('div',undefined,'cover');cover.append(node('span',(item.series_title||'剧').slice(0,2),'cover-fallback'));const img=image(item.cover);if(img)cover.append(img);const hist=state.history.find(h=>h.series_id===item.series_id);cover.append(node('span',target==='history'&&hist?`看到第 ${hist.episodeIndex} 集`:item.episode_label||((item.total||item.episode_count)?`全 ${item.total||item.episode_count} 集`:'红果短剧'),'cover-label'));card.append(cover,node('h3',item.series_title||'未命名短剧'),node('p',target==='history'?'点击继续观看':(item.tags||[]).join(' · ')||'红果 · 公开片源'));$(target).append(card);}}
function syncSavedCounts(){$('fav-count').textContent=state.favorites.length;for(const [id,value]of [['mine-favorites',state.favorites.length],['mine-history',state.history.length],['mine-likes',state.likes.length]]){const el=$(id);if(el)el.textContent=String(value);}}
function renderSaved(key){const items=state[key];syncSavedCounts();if(!items.length){const copy={favorites:['还没有收藏的故事','打开剧集详情，点击「加入追剧」。'],history:['还没有观看记录','播放剧集后，进度会自动留在这里。'],likes:['还没有点赞的故事','打开剧集详情，点击「点赞」留在这里。']}[key];empty(key,copy[0],copy[1]);return;}renderCards(key,items);for(const [index,card]of [...$(key).children].entries()){const wrap=node('div',undefined,'saved-item');card.replaceWith(wrap);wrap.append(card);const remove=action('×',()=>{state[key]=state[key].filter(v=>v.series_id!==items[index].series_id);save(key);renderSaved(key);},'remove-saved');remove.setAttribute('aria-label',{favorites:'取消收藏 ',history:'删除记录 ',likes:'取消点赞 '}[key]+items[index].series_title);wrap.append(remove);}}
function skeleton(target,count=12){$(target).replaceChildren();for(let i=0;i<count;i++){const n=node('div',undefined,'skeleton-card');n.append(node('div',undefined,'cover'),node('p','　'));$(target).append(n);}}
async function loadCatalog(){if(!requireConnection('catalog'))return;const request=++state.request,category=state.category,genre=state.genre,page=state.catalogPage;$('catalog-state').textContent='正在加载…';skeleton('catalog');try{const data=await api(`/catalog?category=${category}&genre=${encodeURIComponent(genre)}&page=${page}`);if(request!==state.request)return;renderCards('catalog',data.results||[]);renderFeatured(data.results||[]);$('catalog-count').textContent=data.results?.length?`${data.results.length} 部`:'';$('catalog-state').textContent=data.results?.length?'':'当前筛选暂无剧集。';$('genres').replaceChildren();for(const g of [{slug:'',label:'全部题材'},...(data.genres||[])])$('genres').append(action(g.label,()=>{if(state.genre===g.slug)state.catalogPage++;else{state.genre=g.slug;state.catalogPage=1;}loadCatalog();},g.slug===state.genre?'selected':''));$('genres').hidden=category.startsWith('hot-');$('catalog-page').textContent=`第 ${page} 页`;$('catalog-prev').hidden=page<=1;$('catalog-next').hidden=!(data.hasMore===true||data.totalPages>page);$('refresh-catalog').disabled=$('catalog-next').hidden;}catch(e){if(request!==state.request)return;$('catalog-state').textContent='';empty('catalog','目录暂时未能加载',e.message);$('catalog').append(action('重试',loadCatalog));}}
for(const b of document.querySelectorAll('[data-category]'))b.onclick=()=>{const repeat=state.category===b.dataset.category&&!state.category.startsWith('hot-');state.category=b.dataset.category;if(repeat)state.catalogPage++;else{state.genre='';state.catalogPage=1;}document.querySelectorAll('[data-category]').forEach(n=>n.classList.toggle('selected',n===b));loadCatalog();};
$('refresh-catalog').onclick=()=>{state.catalogPage++;loadCatalog();};$('catalog-next').onclick=()=>{state.catalogPage++;loadCatalog();};$('catalog-prev').onclick=()=>{state.catalogPage=Math.max(1,state.catalogPage-1);loadCatalog();};
async function search(page=1){if(!requireConnection('results'))return;const q=$('query').value.trim();if(!q)return;const request=++state.request;state.query=q;state.searchPage=page;if(state.view==='search')window.history.replaceState({view:'search'},'','#/search?q='+encodeURIComponent(q)+'&page='+page);if(page===1){state.recent=[q,...state.recent.filter(v=>v!==q)].slice(0,10);saveRecent();renderRecent();}$('search-state').textContent='正在搜索真实片源…';skeleton('results');$('prev').hidden=true;$('next').hidden=true;$('page-label').textContent='';try{const d=await api(`/search?q=${encodeURIComponent(q)}&page=${page}`);if(request!==state.request)return;renderCards('results',d.results||[]);$('search-state').textContent=d.results?.length?`“${q}”的搜索结果`:'没有找到相关剧集，试试其他关键词。';$('page-label').textContent=`第 ${page} 页`;$('prev').hidden=page<=1;$('next').hidden=!d.hasMore;}catch(e){if(request===state.request){$('search-state').textContent=e.message;$('results').replaceChildren(action('重新搜索',()=>search(page)));}}}
$('search-form').onsubmit=e=>{e.preventDefault();search();};$('quick-search').onsubmit=e=>{e.preventDefault();$('query').value=e.currentTarget.querySelector('input').value;showView('search');search();};$('prev').onclick=()=>search(state.searchPage-1);$('next').onclick=()=>search(state.searchPage+1);
async function openSeries(item,fromHistory=false){
 if(!state.token){notice('请先连接红果服务。');showView('settings');return;}
 state.detailHasBack=!fromHistory&&!['series','player','settings'].includes(state.view);
 if(!['series','player','actor'].includes(state.view))state.returnView=state.view;
 showView('series',true);if(!fromHistory)window.history.pushState({view:'series',id:item.series_id},'','#/series/'+item.series_id);
 const request=++state.detailRequest;state.series=null;state.selected.clear();$('detail-body').replaceChildren(node('h1',item.series_title||'剧集详情'),node('p','正在加载剧集…','muted'));scrollMain(0);
 try{const d=await api('/series/'+encodeURIComponent(item.series_id));if(request!==state.detailRequest||state.view!=='series')return;state.series={...item,...d.series,cover:d.series.cover||item.cover};renderDetail();}catch(e){if(request!==state.detailRequest)return;$('detail-body').replaceChildren(node('p',e.message),action('重新加载',()=>openSeries(item,true)));}
}
function closeDetail(){if(state.detailHasBack)window.history.back();else showView(state.returnView||'discover');}
function toggleFavorite(){const s=state.series;if(!s)return;const index=state.favorites.findIndex(n=>n.series_id===s.series_id);if(index>=0)state.favorites.splice(index,1);else state.favorites.unshift(summary(s));save('favorites');syncSavedCounts();renderDetail();}
function toggleLike(){const s=state.series;if(!s)return;const index=state.likes.findIndex(n=>n.series_id===s.series_id);if(index>=0)state.likes.splice(index,1);else state.likes.unshift(summary(s));save('likes');syncSavedCounts();renderDetail();notice(state.likes.some(n=>n.series_id===s.series_id)?'已点赞，保存在当前浏览器。':'已取消点赞。');}
function summary(s){return {series_id:s.series_id,series_title:s.series_title,cover:s.cover,total:s.total||s.episodes?.length,tags:s.tags||[]};}
function renderDetail(){
 const s=state.series;if(!s)return;const root=$('detail-body');root.replaceChildren();
 const intro=node('div',undefined,'series-dossier surface'),cover=node('div',undefined,'dossier-cover');const img=image(s.cover,s.series_title);if(img)cover.append(img);intro.append(cover);
 const info=node('div',undefined,'dossier-info');info.append(node('span','红果短剧','dossier-type'),node('h1',s.series_title));
 const episodesList=Array.isArray(s.episodes)?s.episodes:[];const social=s.social_info||{};info.append(node('p',[s.episode_label||(episodesList.length?`全 ${episodesList.length} 集`:'片源待确认'),social.rating?social.rating+' 分':'',social.hot_text||''].filter(Boolean).join(' · '),'series-meta'));
 if(s.tags?.length){const tags=node('div',undefined,'metadata-tags');for(const tag of s.tags)tags.append(node('span',tag));info.append(tags);}
 info.append(node('h2','剧情简介'),node('p',s.intro||s.description||'暂无剧情简介','series-intro'));
 const controls=node('div',undefined,'detail-actions');const h=state.history.find(n=>n.series_id===s.series_id);const first=episodesList.find(e=>e.vid===h?.vid||e.vid_index===h?.episodeIndex)||episodesList[0];controls.append(action(h?`继续观看 · 第 ${h.episodeIndex} 集`:'立即播放',()=>first?preparePlay(first):notice('当前剧集暂无可用分集。'),'primary'),action(state.favorites.some(n=>n.series_id===s.series_id)?'已追剧':'加入追剧',toggleFavorite),action(state.likes.some(n=>n.series_id===s.series_id)?'已点赞':'点赞',toggleLike));info.append(controls);renderCast(info,s.celebrities||[]);intro.append(info);root.append(intro);
 const episodes=node('div',undefined,'episode-section surface');const heading=node('div',undefined,'section-heading');heading.append(node('h2','选集'),node('span',`共 ${episodesList.length} 集`,'muted'));episodes.append(heading);
 const seasons=node('div',undefined,'seasons-control');seasons.append(action('系列各季',()=>showSeasons(s,seasons),'text-button'));episodes.append(seasons);
 const toolbar=node('div',undefined,'detail-toolbar');const mode=node('input');mode.type='checkbox';mode.id='batch-mode';const label=node('label',' 批量选择下载');label.prepend(mode);const quality=node('select');quality.id='quality';quality.setAttribute('aria-label','下载画质');for(const [v,t]of [['auto','自动画质'],['720p','720P 优先'],['1080p','1080P 优先']]){const o=node('option',t);o.value=v;quality.append(o);}toolbar.append(label,quality,action('全选',()=>{mode.checked=true;state.selected=new Set(s.episodes.map(e=>e.vid));root.querySelectorAll('[data-vid]').forEach(b=>b.classList.add('selected'));}),action('下载选中',()=>submitDownload([...state.selected],quality.value)));toolbar.hidden=!state.owner;episodes.append(toolbar);
 const grid=node('div',undefined,'episode-grid');for(const ep of episodesList){const b=action(String(ep.vid_index),()=>{if(mode.checked){if(state.selected.has(ep.vid))state.selected.delete(ep.vid);else state.selected.add(ep.vid);b.classList.toggle('selected',state.selected.has(ep.vid));}else return preparePlay(ep);});b.dataset.vid=ep.vid;b.setAttribute('aria-label',`第 ${ep.vid_index} 集`);grid.append(b);}if(!episodesList.length)grid.append(node('p','上游暂未返回分集。','muted'));episodes.append(grid);root.append(episodes);
}
async function submitDownload(ids,quality='auto'){if(!state.owner)throw Error('下载仅限本人管理。');if(!ids.length)throw Error('请先选择需要下载的分集。');const series=state.series;const d=await api('/downloads',{seriesId:series.series_id,episodeIds:ids,quality});closeDetail();notice(`已提交 ${d.tasks.length} 个任务。`);await refreshTasks();showView('tasks');return d;}
function renderFeatured(){}
function releaseStream(){if(streamUrl){fetch(streamUrl,{method:'DELETE',credentials:'same-origin'}).catch(()=>{});streamUrl=null;}}
function loading(title,detail){$('player-loading').hidden=false;$('loading-title').textContent=title;$('loading-detail').textContent=detail;$('cancel-prepare').textContent='取消准备';}
function renderTheater(){const s=state.playSeries;if(!s)return;const info=$('theater-info');info.replaceChildren();const row=node('div',undefined,'theater-info-cover');const img=image(s.cover);if(img)row.append(img);const text=node('div');text.append(node('h2',s.series_title),node('p',`全 ${s.episodes.length} 集 · 红果短剧`),action(state.favorites.some(f=>f.series_id===s.series_id)?'♥ 已追剧':'♡ 追这部剧',()=>{const current=state.series;state.series=s;toggleFavorite();state.series=current;renderTheater();}));row.append(text);info.append(row);const extra=$('theater-extra');extra.replaceChildren();if(s.intro)extra.append(node('p',s.intro,'theater-intro'));renderCast(extra,(s.celebrities||[]).slice(0,3));extra.append(action('查看系列各季',()=>showSeasons(s,extra),'text-button'));$('episode-pages').replaceChildren();for(let i=0;i<s.episodes.length;i+=30){const index=Math.floor(i/30);$('episode-pages').append(action(`${i+1}–${Math.min(i+30,s.episodes.length)}`,()=>{episodePage=index;renderTheater();},index===episodePage?'selected':''));}$('theater-episodes').replaceChildren();for(const ep of s.episodes.slice(episodePage*30,(episodePage+1)*30)){const b=action(String(ep.vid_index),()=>{state.series=s;return preparePlay(ep);},state.playing?.vid===ep.vid?'selected':'');b.setAttribute('aria-label',`播放第 ${ep.vid_index} 集`);$('theater-episodes').append(b);}}
async function preparePlay(ep,forceCompatible=false,keepPaused=false){
 const s=state.series;if(!s)return;const request=++playerRequest;playController?.abort();playController=new AbortController();const signal=playController.signal;
 state.pendingPlay=null;record();$('video').pause();releaseStream();$('video').removeAttribute('src');$('video').load();
 state.playSeries=s;episodePage=Math.floor((ep.vid_index-1)/30);const previous=state.history.find(h=>h.series_id===s.series_id&&h.vid===ep.vid);
 state.playing={...summary(s),vid:ep.vid,episodeIndex:ep.vid_index,time:previous?.time||0};
 $('player-title').textContent=`${s.series_title} · 第 ${ep.vid_index} 集 / 全 ${s.episodes.length} 集`;
 showPlayer();
 renderTheater();resetDanmaku();loadDanmaku();$('theater-sidebar').scrollTo({top:0});loading('正在连接片源','仅获取播放所需分段，无需下载整部短剧。');$('player-state').textContent='正在获取完整片源';
 try{
  await api('/session',{},signal);if(request!==playerRequest)return;
  const completed=state.tasks.find(t=>($('playback-quality').value==='auto'||t.quality===$('playback-quality').value)&&t.seriesId===s.series_id&&t.episodeIndex===ep.vid_index&&t.status==='completed'&&t.type==='download');
  if(completed){await playTask(completed,s,keepPaused);return;}
  const supportsHevc=Boolean($('video').canPlayType('video/mp4; codecs="hvc1.1.6.L93.B0"'));
  const data=await api('/play',{seriesId:s.series_id,vid:ep.vid,quality:$('playback-quality').value,compatible:forceCompatible||!supportsHevc},signal);
  if(request!==playerRequest)return;
  if(data.mode==='prepare'){
   loading('正在准备兼容画面','当前编码需要转换，完成后自动播放。进度通过事件实时更新。');
   state.pendingPlay={series:summary(s),vid:ep.vid,request,keepPaused};
   if(!state.owner)throw Error('此片源需要兼容转换，暂仅支持本人管理模式。请尝试其他画质或使用支持该编码的浏览器。');const d=await api('/downloads',{seriesId:s.series_id,episodeIds:[ep.vid],quality:$('playback-quality').value},signal);
   if(request!==playerRequest)return;if(state.pendingPlay)state.pendingPlay.taskId=d.tasks[0]?.id;
   await refreshTasks();return;
  }
  streamUrl=data.url;$('video').muted=prefs.muted;$('video').volume=prefs.volume;$('video').src=streamUrl;$('video').playbackRate=Number($('playback-rate').value);
  $('video').onloadedmetadata=()=>{if(request!==playerRequest)return;if(previous?.time&&previous.time<$('video').duration-2)$('video').currentTime=previous.time;};
  $('player-state').textContent=`流式播放 · ${data.codec.toUpperCase()}${data.width&&data.height?' · '+Math.min(data.width,data.height)+'P':''}`;
  if(keepPaused){$('video').preload='auto';$('player-loading').hidden=true;$('video').pause();return;}
  try{await $('video').play();}catch{$('player-loading').hidden=true;$('player-state').textContent='点击画面中的播放按钮开始';}
 }catch(error){if(request!==playerRequest)return;loading('暂时未能开始播放',error.message);$('cancel-prepare').textContent='返回选集';$('player-state').textContent='可点击「兼容播放」重试本集';}
}
function syncTaskCounts(){const active=state.tasks.filter(t=>['running','queued'].includes(t.status)).length;for(const id of ['task-count','side-task-count'])$(id).textContent=String(active);const mine=$('mine-tasks');if(mine)mine.textContent=String(state.tasks.length);}
function consumeTasks(tasks){state.tasks=tasks;syncTaskCounts();renderTasks();const pending=state.pendingPlay;if(!pending||pending.request!==playerRequest)return;const task=tasks.find(t=>t.id===pending.taskId||(t.seriesId===pending.series.series_id&&t.vid===pending.vid&&['running','queued','completed'].includes(t.status)));if(task?.status==='completed'){state.pendingPlay=null;playTask(task,pending.series,pending.keepPaused).catch(notice);}else if(task&&['failed','interrupted','cancelled'].includes(task.status)){state.pendingPlay=null;loading('播放准备失败',task.error||'请点击兼容播放重试');$('cancel-prepare').textContent='返回选集';}else if(task){$('loading-title').textContent=task.status==='queued'?'正在等待兼容转换':`正在准备画面 ${Math.round(task.progress||0)}%`;$('loading-detail').textContent='兼容转换完成后自动播放；可取消准备或切换其他分集。';}}
const statuses={queued:'等待中',running:'正在处理',completed:'已完成',failed:'失败',interrupted:'已中断',cancelled:'已取消'};
function renderTasks(){if(!state.owner){empty('tasks','下载管理仅限本人','访客可以浏览和在线播放，不能查看或操作下载任务。');return;}if(!state.token){requireConnection('tasks');return;}$('tasks').replaceChildren();if(!state.tasks.length){empty('tasks','还没有下载任务','从剧集详情选择分集，开始播放或保存。');return;}for(const t of state.tasks){const row=node('article',undefined,'task');const info=node('div');info.append(node('h3',`${t.seriesTitle} · ${t.type==='merge'?'合并文件':`第 ${t.episodeIndex} 集`}`),node('p',`${statuses[t.status]||t.status}${t.status==='running'?` · ${Math.round(t.progress||0)}%`:''} · ${t.quality||'MP4'}`));if(t.status==='running'){const p=node('progress');p.max=100;p.value=t.progress||0;info.append(p);}if(t.error)info.append(node('p',t.error));const buttons=node('span',undefined,'task-actions');if(t.status==='completed')buttons.append(action('▶ 播放',()=>playTask(t)),action('保存文件',()=>downloadFile(t)));if(['running','queued'].includes(t.status))buttons.append(action('取消',()=>taskAction(t.id,'cancel')));if(['failed','cancelled','interrupted'].includes(t.status))buttons.append(action('重试',()=>taskAction(t.id,'retry')));if(t.type==='download'&&t.status==='completed'){const check=node('input');check.type='checkbox';check.className='merge-checkbox';check.setAttribute('aria-label','选择合并第 '+t.episodeIndex+' 集');check.checked=state.mergeSelected.has(t.id);check.onchange=()=>{if(check.checked)state.mergeSelected.add(t.id);else state.mergeSelected.delete(t.id);$('merge-selected').hidden=state.mergeSelected.size<2;};row.append(check);}row.append(info,buttons);$('tasks').append(row);}}
