async function subscribe(){eventController?.abort();if(!state.owner)return;const c=new AbortController();eventController=c;const generation=state.generation;try{const res=await fetch('/api/events',{headers:{Authorization:'Bearer '+state.token},signal:c.signal});if(!res.ok)throw Error('事件连接失败');$('events-state').textContent='实时事件已连接 · 无需手动刷新';const reader=res.body.getReader(),decoder=new TextDecoder();let buffer='';for(;;){const {done,value}=await reader.read();if(done)break;if(generation!==state.generation)break;buffer+=decoder.decode(value,{stream:true});let i;while((i=buffer.indexOf('\n\n'))>=0){const line=buffer.slice(0,i);buffer=buffer.slice(i+2);if(line.startsWith('data: ')){const d=JSON.parse(line.slice(6));consumeTasks(d.tasks||[]);}}}if(generation===state.generation)$('events-state').textContent='事件连接已关闭，点击「刷新状态」获取最新结果。';}catch(e){if(e.name!=='AbortError'&&generation===state.generation)$('events-state').textContent='实时连接中断，请点击刷新状态。';}}
async function playTask(task,series,keepPaused=false){if(task.status!=='completed')return;const generation=state.generation;await api('/session',{});if(generation!==state.generation)return;const metadata=series||state.history.find(h=>h.series_id===task.seriesId)||{series_id:task.seriesId,series_title:task.seriesTitle};const h=state.history.find(h=>h.series_id===task.seriesId&&(h.vid===task.vid||h.episodeIndex===task.episodeIndex));state.playing={...summary(metadata),series_id:task.seriesId,series_title:task.seriesTitle,vid:task.vid,episodeIndex:task.episodeIndex||1,time:h?.time||0};$('player-title').textContent=`${task.seriesTitle} · 第 ${task.episodeIndex||1} 集`;$('player-state').textContent='兼容播放 · H.264 / AAC';const video=$('video');video.muted=prefs.muted;video.volume=prefs.volume;releaseStream();video.src='/api/files/'+task.id;video.playbackRate=Number($('playback-rate').value);video.onloadedmetadata=()=>{if(h?.time&&h.time<video.duration-2)video.currentTime=h.time;};showPlayer();$('player-loading').hidden=true;if(!state.playSeries||state.playSeries.series_id!==task.seriesId){const d=await api('/series/'+task.seriesId);state.playSeries={...metadata,...d.series};}episodePage=Math.floor(((task.episodeIndex||1)-1)/30);renderTheater();resetDanmaku();loadDanmaku();$('theater-sidebar').scrollTo({top:0});if(keepPaused){video.pause();return;}try{await video.play();}catch{$('player-state').textContent='点击播放按钮开始观看';}}
