$('danmaku-speed').onchange=()=>{prefs.speed=Number($('danmaku-speed').value);savePrefs();};$('danmaku-rows').onchange=()=>{prefs.rows=Number($('danmaku-rows').value);laneFree=[];savePrefs();};$('retry-danmaku').onclick=()=>{danmakuItems=[];danmakuIndex=0;loadDanmaku();};
function emitDanmaku(item,time){const layer=$('danmaku-layer'),row=Array.from({length:prefs.rows},(_,i)=>i).find(i=>(laneFree[i]||0)<=time);if(row===undefined||layer.childElementCount>30)return;laneFree[row]=time+2;const span=node('span',item.text,'danmaku');span.style.top=`${8+row*30}px`;if(/^#[a-f0-9]{6}$/i.test(item.color))span.style.color=item.color;const fixed=['top','bottom'].includes(item.mode);if(fixed){span.classList.add('fixed');if(item.mode==='bottom'){span.style.top='auto';span.style.bottom=`${55+row*30}px`;}}span.style.setProperty('--travel',`-${layer.clientWidth+1000}px`);span.style.animationDuration=`${(fixed?4:prefs.speed)/$('video').playbackRate}s`;span.style.animationPlayState=$('video').paused?'paused':'running';span.addEventListener('animationend',()=>span.remove(),{once:true});layer.append(span);}
$('video').addEventListener('timeupdate',()=>{const v=$('video');if(prefs.danmaku&&!v.seeking){let count=0;while(danmakuIndex<danmakuItems.length&&danmakuItems[danmakuIndex].time<=v.currentTime){const item=danmakuItems[danmakuIndex++];if(v.currentTime-item.time<1&&count++<prefs.rows)emitDanmaku(item,v.currentTime);}}const p=state.playing,s=state.playSeries;if(prefs.prefetch&&p&&s&&v.duration-v.currentTime<=20&&v.duration>0&&!v.paused){const next=s.episodes.find(e=>e.vid_index===p.episodeIndex+1),key=next?.vid+':'+prefs.quality;if(next&&key!==prefetchedKey){prefetchedKey=key;prefetchController?.abort();prefetchController=new AbortController();api('/prefetch',{seriesId:s.series_id,vid:next.vid,quality:prefs.quality},prefetchController.signal).catch(()=>{});}}});
$('video').addEventListener('seeked',()=>{$('danmaku-layer').replaceChildren();laneFree=[];const index=danmakuItems.findIndex(i=>i.time>=$('video').currentTime);danmakuIndex=index<0?danmakuItems.length:index;});
for(const event of ['play','pause'])$('video').addEventListener(event,()=>{$('danmaku-layer').style.setProperty('--danmaku-state',$('video').paused?'paused':'running');for(const n of $('danmaku-layer').children)n.style.animationPlayState=$('video').paused?'paused':'running';});

