 if((parts[0]==='play'||parts[0]==='watch')&&parts.length===3&&/^\d{1,30}$/.test(parts[1])&&/^\d{1,30}$/.test(parts[2])){try{const d=await api('/series/'+parts[1]);state.series=d.series;const ep=d.series.episodes?.find(e=>e.vid===parts[2]);if(ep)return preparePlay(ep);notice('没有找到这一集，已打开剧集详情。');return openSeries(d.series,true);}catch(e){notice(e);return showView('history',true);}}
