async function bootstrap(){try{
 const route=location.hash.slice(2).split('?')[0];
 if(route==='owner'){
  const code=new URLSearchParams(location.hash.split('?')[1]||'').get('code');
  window.history.replaceState(null,'','#/settings');
  const login=await fetch('/api/owner/login',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({code})});
  if(!login.ok){const d=await login.json();notice(d.error||'管理授权已失效');}
  else window.history.replaceState(null,'','#/tasks');
 }
 const r=await fetch('/api/status',{credentials:'same-origin'});if(!r.ok)return routeCurrent();const d=await r.json();
 state.owner=d.owner===true;applyAccess();
 if(!d.openAccess&&!state.owner)return routeCurrent();state.token=d.openAccess?'public':'owner';$('service-card').hidden=true;applyAccess();renderMine();
 subscribe();if(state.owner)await refreshTasks();await routeCurrent(true);
 }catch{notice('服务暂不可用，请刷新重试。');}}

