(()=>{const v=$('video'),play=$('video-play'),seek=$('video-seek'),mute=$('video-mute'),volume=$('video-volume');const fmt=n=>{n=Number.isFinite(n)?Math.floor(n):0;return `${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`};function sync(){play.textContent=v.paused?'▶':'❚❚';play.setAttribute('aria-label',v.paused?'播放':'暂停');$('video-time').textContent=`${fmt(v.currentTime)} / ${fmt(v.duration)}`;if(!seek.matches(':active'))seek.value=Number.isFinite(v.duration)&&v.duration>0?String(Math.round(v.currentTime/v.duration*1000)):'0';mute.textContent=v.muted||v.volume===0?'静音':'音量';mute.setAttribute('aria-label',v.muted?'取消静音':'静音');volume.value=String(v.volume)}play.onclick=()=>v.paused?v.play().catch(()=>{}):v.pause();v.addEventListener('click',()=>v.paused?v.play().catch(()=>{}):v.pause());seek.oninput=()=>{if(Number.isFinite(v.duration))v.currentTime=Number(seek.value)/1000*v.duration};mute.onclick=()=>{v.muted=!v.muted};volume.oninput=()=>{v.volume=Number(volume.value);v.muted=v.volume===0};for(const event of ['timeupdate','durationchange','play','pause','volumechange','loadedmetadata'])v.addEventListener(event,sync);sync();document.addEventListener('click',event=>{for(const menu of document.querySelectorAll('.control-menu[open]'))if(!menu.contains(event.target))menu.open=false;});})();
